 function exportSubmissionData(){
  const exportData={
   document_type:"Galini applicant submission data",
   schema_version:"1.0",
   generated_at:new Date().toISOString(),
   notice:"This is structured applicant data for internal review or an authorized ACORD integration. It is not an ACORD form and must not be represented as one.",
   applicant:{...v},
   line_of_business:line,
   schedules:{vehicles,drivers,premises:locations},
   selected_coverages:{...v},
   classification:{naics_code:v.naics_code||null,naics_description:v.naics_description||null,insurance_class_code:null,insurance_class_status:"Not verified — do not use as a rating code"},
   review:{missing_core_fields:[...(!v.named_insured.trim()?["Named insured"]:[]),...(!v.effective_date?["Effective date"]:[]),...(!v.state?["State"]:[]),...(commercial&&!v.operations.trim()?["Business operations"]:[])],requires_agent_review:true}
  };
  const blob=new Blob([JSON.stringify(exportData,null,2)],{type:"application/json"});
  const url=URL.createObjectURL(blob);
  const link=document.createElement("a");
  link.href=url;
  link.download=(v.named_insured||"applicant").replace(/[^a-z0-9-_]+/gi,"_")+"_galini_submission.json";
  document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);
 }
